(function(root){
 'use strict';let data,esc,md,sourceLink,link;
 function configure(o){({data,esc,md,sourceLink,link}=o);}
 function snippet(c){
  let imports=c.library==='NumPy'?'import numpy as np\n':c.library==='PyTorch'?'import torch\nfrom torch import nn\nimport torch.nn.functional as F\n':'';
  if(c.library!=='NumPy'&&/\bnp\./.test(c.setup+c.code))imports+='import numpy as np\n';
  if(c.library!=='PyTorch'&&/\btorch\./.test(c.setup+c.code))imports+='import torch\n';
  return imports+'\n'+c.setup+'\n\n'+c.code;
 }
 function answer(c){return `<div class="code-answer"><div class="code-toolbar"><strong>${esc(c.focus)}</strong><button type="button" class="btn quiet small" data-copy-card="${c.id}">Скопировать ячейку</button></div><pre tabindex="0"><code>${esc(snippet(c))}</code></pre><h4>Что получится</h4><p>${esc(c.result)}</p><h4>Почему</h4><p>${esc(c.explanation)}</p><div class="callout warning"><strong>Тонкость</strong>${esc(c.trap)}</div><a class="source-link" href="${esc(c.doc)}" target="_blank" rel="noopener noreferrer">Документация API ↗</a></div>`;}
 function related(topic){const cards=(topic.codeCards||[]).map(id=>data.codeCards.find(c=>c.id===id));if(!cards.length)return '';
  return `<section class="code-extras"><h2>Дополнительные ячейки кода · ${cards.length}</h2><p class="inline-note">Одна ячейка — одна операция. Это дополнительные упражнения API по теме конспекта на учебных данных.</p>${cards.map(c=>`<details class="code-cell"><summary>${esc(c.library)} · ${esc(c.focus)}</summary><p>${esc(c.prompt)}</p>${answer(c)}<a class="btn secondary small" href="${link('code',{card:c.id})}">Задача и контекст →</a></details>`).join('')}</section>`;}
 function page(p){
  const lib=p.get('library')||'',lesson=p.get('lesson')||'',query=p.get('q')||'';
  const pool=data.codeCards.filter(c=>(!lib||c.library===lib)&&(!lesson||c.lesson===Number(lesson))&&(!query||[c.focus,c.prompt,c.explanation,c.code].join(' ').toLowerCase().includes(query.toLowerCase())));
  const chosen=pool.find(c=>c.id===p.get('card'))||pool[0],i=pool.indexOf(chosen);
  return `<div class="intro"><div class="eyebrow">ОДНА ОПЕРАЦИЯ → ОБЪЯСНЕНИЕ → ПРАКТИКА</div><h1>Практика кода и API.</h1><p>${data.codeCards.length} коротких задач: тензоры, память, broadcasting, градиенты, causal masks, обучение, модели, сегментация, Lightning, TensorBoard и MLflow.</p></div><form id="code-filter" class="code-filter"><label>Библиотека<select name="library"><option value="">Все</option>${[...new Set(data.codeCards.map(c=>c.library))].map(x=>`<option ${x===lib?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label>Материал<select name="lesson"><option value="">Все уроки</option>${data.lessons.map(l=>`<option value="${l.id}" ${String(l.id)===lesson?'selected':''}>${l.id} · ${esc(l.short)}</option>`).join('')}</select></label><label>Операция или задача<input name="q" value="${esc(query)}" placeholder="causal, backward, reshape…"></label><button class="btn small" type="submit">Найти</button></form><p class="inline-note">Найдено: ${pool.length}. Код предназначен для Python; браузер его не исполняет. CPU-примеры и ячейки Lightning, TensorBoard, MLflow проверяются на синтетических данных в Python; для инструментов нужны установленные библиотеки. Интеграционные ячейки требуют указанных внешних зависимостей/weights и не скачивают их автоматически при открытии страницы.</p>${chosen?`<label class="code-picker">Задача<select id="code-picker">${pool.map(c=>`<option value="${c.id}" ${c.id===chosen.id?'selected':''}>${esc(c.library+' · '+c.focus+' · '+c.prompt)}</option>`).join('')}</select></label><article class="panel code-task"><div class="eyebrow">${i+1} / ${pool.length} · ${esc(chosen.library)} · ${chosen.runtime==='cpu'?'CPU-ПРИМЕР':chosen.runtime==='tooling'?'ЛОКАЛЬНЫЙ PYTHON · НУЖНЫ БИБЛИОТЕКИ':'ВНЕШНЯЯ ИНТЕГРАЦИЯ'}</div><h2>${esc(chosen.focus)}</h2><p class="lead">${esc(chosen.prompt)}</p><h3>Что дано</h3><pre tabindex="0"><code>${esc(chosen.setup)}</code></pre><p>Сначала сформулируйте одну нужную операцию и предскажите форму, dtype или результат. Затем раскройте разбор.</p><details class="code-solution"><summary>Показать ответ и обоснование</summary>${answer(chosen)}</details><p class="inline-note">${esc(chosen.basis)}</p><div class="actions"><a class="btn" href="${link('practice',{collection:chosen.collection||'code',card:chosen.id,count:'all'})}">Ответить в тренировке →</a><a class="btn secondary" href="${link('theory',{lesson:chosen.lesson,topic:chosen.topics[0]})}">Теория по теме</a></div><div class="code-pagination">${i>0?`<a href="${link('code',{library:lib,lesson,q:query,card:pool[i-1].id})}">← Предыдущая</a>`:''}${i+1<pool.length?`<a href="${link('code',{library:lib,lesson,q:query,card:pool[i+1].id})}">Следующая →</a>`:''}</div></article>`:'<div class="panel">Ничего не найдено. Измените фильтр.</div>'}<div class="actions"><a class="btn secondary" href="${link('practice',{collection:'code',count:10})}">Случайные задачи по коду →</a><a class="source-link" href="#materials">Какие семинары и ДЗ учтены →</a></div>`;
 }
 function materials(){const files=(root.CV_SOURCES||[]).filter(s=>/seminar|homework|cv_hw|\/hw\//i.test(s.path));
  return `<div class="intro"><div class="eyebrow">СЕМИНАРЫ И ДОМАШНИЕ ЗАДАНИЯ</div><h1>Практические материалы курса.</h1><p>Теория, вопросы и дополнительные ячейки кода по урокам 1–6. Здесь пересказаны механизмы и разобраны учебные примеры; исходные личные работы остаются в локальной копии.</p></div>${files.map(s=>{const ts=data.topics.filter(t=>t.source.path===s.path);return `<article class="panel material-card"><span class="eyebrow">УРОК ${s.lesson} · ${s.document?'ДОКУМЕНТ':'НОУТБУК'}</span><h2>${esc(s.path)}</h2><p>${s.cellCount} непустых ячеек/документов в локальном снимке</p><div class="actions">${ts.map(t=>`<a class="btn secondary small" href="${link('theory',{lesson:t.lesson,topic:t.id})}">${esc(t.title)}</a>`).join('')}<a class="source-link" href="${link('source',{path:s.path})}">Открыть локальный оригинал ↗</a></div></article>`;}).join('')}`;
 }
 function bind(container){
  const f=container.querySelector('#code-filter');if(f)f.addEventListener('submit',e=>{e.preventDefault();location.hash=link('code',Object.fromEntries(new FormData(f)));});
  const picker=container.querySelector('#code-picker');if(picker)picker.addEventListener('change',()=>{const p=new URLSearchParams(location.hash.split('?')[1]||'');p.set('card',picker.value);location.hash='#code?'+p;});
  for(const b of container.querySelectorAll('[data-copy-card]'))b.addEventListener('click',async()=>{
   const c=data.codeCards.find(c=>c.id===b.dataset.copyCard);
   try{await navigator.clipboard.writeText(snippet(c));b.textContent='Скопировано';}
   catch(e){const code=b.closest('.code-answer').querySelector('code'),range=document.createRange();range.selectNodeContents(code);const s=getSelection();s.removeAllRanges();s.addRange(range);b.textContent='Код выделен · Ctrl+C';}
  });
 }
 root.CVCode={configure,page,related,materials,bind};
})(window);
